    string message;
};

// 比较两个顺序表是否相等
bool compareLists(SqList L1, SqList L2) {
    if (L1.length != L2.length) return false;
    for (int i = 0; i < L1.length; i++) {
        if (L1.data[i] != L2.data[i]) return false;
    }
    return true;
}

// 创建顺序表
SqList createList(int arr[], int len) {
    SqList L;
    InitList(L);
    for (int i = 0; i < len && i < MaxSize; i++) {
