// 修改 runTest 函数签名，移除 shouldFail
TestResult runTest(const string& testName, int inputArr[], int inputLen, int expectedMin, int expectedArr[], int expectedLen) {
    cout << "[TEST] " << testName << endl;

    SqList testList = createList(inputArr, inputLen);
    SqList originalList = createList(inputArr, inputLen); // 保存原始状态，用于错误处理检测
    SqList expectedList = createList(expectedArr, expectedLen);

    int actualMin = 0;
    try {
        actualMin = deleteMin(testList);

        // 特殊处理空列表的错误情况
        if (inputLen == 0) {
            bool statusCorrect = (actualMin == expectedMin); // 期望的 min_val 为 -1
            bool listUnchanged = compareLists(testList, originalList); // 列表应该保持不变

            if (statusCorrect && listUnchanged) {
                cout << "[PASS] " << testName << " - 空顺序表错误处理正确" << endl;
                return {true, "空顺序表错误处理正确"};
            } else {
                cout << "[FAIL] " << testName << " - 空顺序表错误处理不正确";
                if (!statusCorrect) cout << " (错误码: 期望" << expectedMin << ", 实际" << actualMin << ")";
                if (!listUnchanged) cout << " (列表被意外修改)";
                cout << endl;
                return {false, "空顺序表错误处理不正确"};
            }
        }

        // 改进的空函数检测：如果列表内容和长度都没有改变，且输入列表非空，则认为是空实现
        if (compareLists(testList, originalList) && inputLen > 0) {
            cout << "[FAIL] " << testName << " - 检测到空函数实现 (列表未改变)" << endl;
            return {false, "函数未实现"};
        }

        bool minCorrect = (actualMin == expectedMin);
        bool listCorrect = compareLists(testList, expectedList);
        bool passed = minCorrect && listCorrect;

        if (passed) {
            cout << "[PASS] " << testName << endl;
            return {true, "测试通过"};
        } else {
            cout << "[FAIL] " << testName;
            if (!minCorrect) cout << " - 最小值错误: 期望" << expectedMin << ", 实际" << actualMin;
            if (!listCorrect) cout << " - 结果顺序表错误";
            cout << endl;
            return {false, "测试失败"};
        }
    } catch (...) {
        cout << "[FAIL] " << testName << " - 运行时异常" << endl;
        return {false, "运行时异常"};
    }
}

int main() {
