    // 测试用例1：正常删除最小值
    int input1[] = {3, 1, 4, 2, 5};
    int expected1[] = {3, 5, 4, 2};
    results.push_back(runTest("正常删除最小值", input1, 5, 1, expected1, 4));

    // 测试用例2：单元素顺序表
    int input2[] = {7};
    int expected2[] = {};
    results.push_back(runTest("单元素顺序表", input2, 1, 7, expected2, 0));

    // 测试用例3：空顺序表处理 (期望返回错误码-1)
    int input3[] = {};
    int expected3[] = {}; // 结果列表内容不重要，因为是错误情况
    results.push_back(runTest("空顺序表处理", input3, 0, -1, expected3, 0));

    // 统计结果
    int passed = 0;
    for (const auto& result : results) {
        if (result.passed) passed++;
    }

    cout << "[RESULT] " << passed << "/" << results.size() << " tests passed" << endl;

    // 如果所有测试都失败，很可能是空函数实现
    if (passed == 0) {
        cout << "[SCORE] 0" << endl;
    } else {
        cout << "[SCORE] " << (passed * 100 / (int)results.size()) << endl;
    }

    return passed == results.size() ? 0 : 1;
}

