    try {
        actualStatus = ListInsert(testList, pos, elem);

        // 特殊处理错误情况 (无效位置或列表已满)
        if (expectedStatus != 0) { // 如果预期状态不是成功 (0)，则这是一个错误测试用例
            bool statusCorrect = (actualStatus == expectedStatus);
