        bool statusCorrect = (actualStatus == expectedStatus); // 检查成功状态码
        bool passed = listContentCorrect && statusCorrect;

        if (passed) {
            cout << "[PASS] " << testName << endl;
            return {true, "测试通过"};
        } else {
            cout << "[FAIL] " << testName;
            if (!statusCorrect) cout << " - 返回状态错误: 期望" << expectedStatus << ", 实际" << actualStatus;
            if (!listContentCorrect) cout << " - 结果顺序表不正确";
            cout << endl;
            return {false, "测试失败"};
