    int input4[] = {1, 2};
    int expected4[] = {}; // 结果列表内容不重要
    results.push_back(runTest("无效位置处理", input4, 2, 10, 5, expected4, 0, -1)); // 期望状态-1 (无效位置/列表已满)

    // 测试用例5：顺序表已满处理 (期望返回错误码-1)
    int input5[MaxSize];
    for(int i=0; i<MaxSize; ++i) input5[i] = i+1; // 填充满列表
