    for (size_t i = 1; i < nodes.size(); ++i) {
        current->next = new ListNode(nodes[i]);
        current = current->next;
    }
    return head;
}

// 辅助函数：将链表转换为向量以便比较
vector<int> listToVector(ListNode* head) {
    vector<int> res;
    ListNode* current = head;
    while (current) {
        res.push_back(current->val);
        current = current->next;
    }
    return res;
}

// 辅助函数：删除链表节点
